    internal static let operationString =
      "subscription OnPhoneNumberUpdate($owner: ID!) {\n  onPhoneNumberUpdate(owner: $owner) {\n    __typename\n    ...PhoneNumberFragment\n  }\n}"
    internal static var requestString: String { return operationString.appending(PhoneNumberFragment.fragmentString) }

    internal var owner: GraphQLID
    internal init(owner: GraphQLID) { self.owner = owner }
    internal var variables: GraphQLMap? { return ["owner": owner] }

    internal struct Data: GraphQLSelectionSet {
      internal static let possibleTypes = ["Subscription"]
      internal static let selections: [GraphQLSelection] = [
        GraphQLField("onPhoneNumberUpdate", arguments: ["owner": GraphQLVariable("owner")], type: .object(PhoneNumberFragment.selections)),
      ]
      internal var snapshot: Snapshot
      internal init(snapshot: Snapshot) { self.snapshot = snapshot }
      internal var onPhoneNumberUpdate: PhoneNumberFragment? {
        guard let s = snapshot["onPhoneNumberUpdate"] as? Snapshot else { return nil }
        return PhoneNumberFragment(snapshot: s)
      }
    }
  }

